#!/usr/bin/env node
// Fails when one change touches both a game plugin and core code.
//
// Games are standalone: a game PR changes only its own games/<name>/ directory.
// If a game needs something new from core, that goes in (and is reviewed) as
// its own PR first.
//
// Usage: node scripts/check-pr-boundary.mjs [base-ref]   (default: origin/main)
import { execFileSync } from "node:child_process";

// Files a game PR may legitimately touch outside its own directory.
const ALLOWED_WITH_A_GAME = new Set([
  "lib/games/registry.ts", // generated by scripts/sync-games.mjs
  "package.json", // a game's own dependency
  "package-lock.json",
]);

const base = process.argv[2] ?? "origin/main";
const changed = execFileSync("git", ["diff", "--name-only", `${base}...HEAD`], { encoding: "utf8" })
  .split("\n")
  .filter(Boolean);

const games = new Set();
const core = [];
for (const file of changed) {
  const game = file.match(/^games\/([^/]+)\//);
  if (game) games.add(game[1]);
  else if (!ALLOWED_WITH_A_GAME.has(file)) core.push(file);
}

if (games.size > 0 && core.length > 0) {
  console.error(`This change touches game code (${[...games].join(", ")}) and core code together:\n`);
  for (const file of core) console.error(`  ${file}`);
  console.error("\nSplit it: land the core change as its own PR first, then the game change.");
  process.exit(1);
}

const what = games.size > 0 ? `game-only (${[...games].join(", ")})` : core.length > 0 ? "core-only" : "empty";
console.log(`Boundary check passed: ${what}, ${changed.length} file(s) changed.`);
